const seed = 424242;
const version = '2026-09-15-v2';
const periodStart = '2026-01-01';
const counts = { companies: 20, contacts: 100, deals: 40, activities: 200 };

function mulberry32(s) {
  let state = s >>> 0;
  return function () {
    state = (state + 0x6d2b79f5) >>> 0;
    let z = state;
    z = Math.imul(z ^ (z >>> 15), z | 1);
    z ^= z + Math.imul(z ^ (z >>> 7), z | 61);
    return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(seed);

const industries = ['FinTech', 'SaaS', 'Logistik', 'Gesundheitswesen', 'Automotive', 'E-Commerce', 'Industrie 4.0', 'Recht & Steuern'];
const cities = ['Berlin', 'München', 'Hamburg', 'Frankfurt', 'Köln', 'Stuttgart', 'Düsseldorf', 'Wien', 'Zürich'];

const companies = [];
for (let i = 1; i <= counts.companies; i++) {
  const id = `co-v2-${i}`;
  companies.push({
    id,
    name: `Unternehmen V2 ${i} GmbH`,
    domain: `firma-v2-${i}.de`,
    industry: industries[Math.floor(rand() * industries.length)],
    city: cities[Math.floor(rand() * cities.length)],
    postalCode: String(10000 + Math.floor(rand() * 89999)),
    employeeCount: Math.floor(Math.exp(3 + rand() * 2))
  });
}

const contacts = [];
for (let i = 1; i <= counts.contacts; i++) {
  const co = companies[Math.floor(rand() * companies.length)];
  contacts.push({
    id: `ct-v2-${i}`,
    companyId: co.id,
    firstName: `Vorname${i}`,
    lastName: `Nachname${i}`,
    email: `kontakt${i}@${co.domain}`,
    jobTitle: 'Sales Director'
  });
}

const stages = ['LEAD', 'QUALIFIED_LEAD', 'PITCH_DEMO', 'PROPOSAL', 'CLOSING', 'WON', 'LOST'];
const deals = [];
for (let i = 1; i <= counts.deals; i++) {
  const co = companies[Math.floor(rand() * companies.length)];
  deals.push({
    id: `fd-v2-${i}`,
    companyId: co.id,
    dealName: `Deal V2 #${i} - ${co.name}`,
    stage: stages[Math.floor(rand() * stages.length)],
    amount: Math.round((5000 + rand() * 45000) / 1000) * 1000,
    closeDate: '2026-06-30',
    pipeline: 'Core Sales'
  });
}

const activities = [];
for (let i = 1; i <= counts.activities; i++) {
  const co = companies[Math.floor(rand() * companies.length)];
  activities.push({
    id: `ac-v2-${i}`,
    companyId: co.id,
    type: 'CALL',
    channel: 'Phone',
    timestamp: '2026-03-15T10:00:00.000Z',
    description: `Followup Call #${i}`,
    performedBy: 'Sales Agent',
    status: 'COMPLETED'
  });
}

const audit = {
  companiesLoaded: companies.length,
  companiesValid: companies.length,
  companiesErrors: 0,
  contactsLoaded: contacts.length,
  contactsValid: contacts.length,
  contactsMatched: contacts.length,
  contactsErrors: 0,
  dealsLoaded: deals.length,
  dealsValid: deals.length,
  dealsErrors: 0
};

return [{
  json: {
    version,
    generatedAt: new Date().toISOString(),
    generator: 'n8n',
    generatorSeed: seed,
    periodStart,
    counts: {
      companies: companies.length,
      contacts: contacts.length,
      deals: deals.length,
      activities: activities.length
    },
    companies,
    contacts,
    importedFunnelDeals: deals,
    activities,
    audit
  }
}];
